query AaveV3HourlyTrending($oneHourAgo: Int!) {
  supplies(
    first: 1000
    where: { timestamp_gte: $oneHourAgo }
    orderBy: timestamp
    orderDirection: desc
  ) {
    timestamp
    amount
    assetPriceUSD
    reserve { symbol decimals }
  }
  borrows(
    first: 1000
    where: { timestamp_gte: $oneHourAgo }
    orderBy: timestamp
    orderDirection: desc
  ) {
    timestamp
    amount
    assetPriceUSD
    reserve { symbol decimals }
  }
  repays(
    first: 1000
    where: { timestamp_gte: $oneHourAgo }
    orderBy: timestamp
    orderDirection: desc
  ) {
    timestamp
    amount
    assetPriceUSD
    reserve { symbol decimals }
  }
  redeemUnderlyings(
    first: 1000
    where: { timestamp_gte: $oneHourAgo }
    orderBy: timestamp
    orderDirection: desc
  ) {
    timestamp
    amount
    assetPriceUSD
    reserve { symbol decimals }
  }
  liquidationCalls(
    first: 200
    where: { timestamp_gte: $oneHourAgo }
    orderBy: timestamp
    orderDirection: desc
  ) {
    timestamp
    collateralAmount
    principalAmount
    collateralAssetPriceUSD
    borrowAssetPriceUSD
    collateralReserve { symbol decimals }
    principalReserve { symbol decimals }
  }
}

query LendingProtocolMetrics($first: Int!) {
  protocols(first: $first) {
    id
    name
    slug
    schemaVersion
    methodologyVersion
    totalValueLockedUSD
    cumulativeUniqueUsers
  }
  markets(first: 25, orderBy: totalValueLockedUSD, orderDirection: desc) {
    id
    name
    totalValueLockedUSD
    totalDepositBalanceUSD
    totalBorrowBalanceUSD
    inputToken { symbol decimals }
  }
  marketSnapshots: marketDailySnapshots(first: 50, orderBy: timestamp, orderDirection: desc) {
    timestamp
    totalValueLockedUSD
    dailyDepositUSD
    dailyBorrowUSD
    market { id }
  }
  protocolSnapshots: marketDailySnapshots(first: 30, orderBy: timestamp, orderDirection: desc) {
    timestamp
    totalValueLockedUSD
    dailyDepositUSD
    dailyBorrowUSD
    dailyLiquidateUSD
  }
}

